                post_hook={
                    "sql": "CREATE OR REPLACE TABLE cp_2 as( select * from ( SELECT *, CASE WHEN DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE) > MAX_SLA THEN \'breach\' ELSE \'non-breach\' END AS breach_flag, (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) AS breach_date, CASE WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) < -2 THEN \'-3\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = -2 THEN \'-2\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = -1 THEN \'-1\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 0 THEN \'0\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 1 THEN \'1\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 2 THEN \'2\' ELSE \'3\' END AS breach_date_category, (DATEDIFF(\'hour\', OUTFORDELIVERY_DATE, MAX_SLA) * -1) AS breach_hours, DATEDIFF(\'hour\', PICKUP_DATE, OUTFORDELIVERY_DATE) AS actual_sla_shipping_hrs, DATEDIFF(\'day\', PICKUP_DATE, OUTFORDELIVERY_DATE) AS actual_sla_shipping_days, DATEDIFF(\'hour\', ORDER_DATE, OUTFORDELIVERY_DATE) AS actual_sla_delivery_hrs, DATEDIFF(\'day\', ORDER_DATE,OUTFORDELIVERY_DATE ) AS actual_sla_delivery_days, DATEDIFF(\'hour\', ORDER_DATE, delivery_date) AS actual_sla_delivered_hrs, DATEDIFF(\'day\', ORDER_DATE,delivery_date ) AS actual_sla_delivered_days, DATEDIFF(\'day\',PICKUP_DATE,MAX_SLA) AS predicted_tat FROM cp_1 where order_date > \'2024-07-01\' AND status = \'DELIVERED\' AND JOURNEY= \'Forward\' )A left join ( select * from ( SELECT ZONE AS Zone_m, City_Tier AS City_Tier, Delivery_Postcode, ROW_NUMBER() OVER (PARTITION BY Delivery_Postcode ORDER BY 1) AS rn FROM snitch_db.maplemonk.pincodemappingzoneupdatedsnitch ) WHERE rn=1) B on A.PINCODE = B.DELIVERY_POSTCODE ); CREATE OR REPLACE TABLE cp_4 as ( select * from ( WITH weekly_pincode_volume AS ( SELECT PINCODE, DATE_TRUNC(\'WEEK\', OUTFORDELIVERY_DATE) AS week, COUNT(*) AS order_count, COUNT(CASE WHEN breach_flag = \'breach\' THEN 1 END) AS breach_count FROM cp_2 GROUP BY PINCODE, DATE_TRUNC(\'WEEK\', OUTFORDELIVERY_DATE) ), ranked_pincodes AS ( SELECT PINCODE, week, order_count, order_count::FLOAT / SUM(order_count) OVER (PARTITION BY week) AS pincode_weekly_percentage, breach_count, (breach_count::FLOAT / order_count) * 100 AS breach_percentage FROM weekly_pincode_volume ), pincode_percentage AS ( SELECT PINCODE, week, order_count, breach_percentage, SUM(pincode_weekly_percentage) OVER (PARTITION BY week ORDER BY pincode_weekly_percentage DESC, PINCODE) AS cumulative_percentage FROM ranked_pincodes ) SELECT PINCODE, week, order_count, cumulative_percentage,breach_percentage, CASE WHEN cumulative_percentage <= 0.10 THEN \'top10%\' WHEN cumulative_percentage > 0.10 AND cumulative_percentage <= 0.20 THEN \'top10-20%\' WHEN cumulative_percentage > 0.20 AND cumulative_percentage <= 0.30 THEN \'top20-30%\' WHEN cumulative_percentage > 0.30 AND cumulative_percentage <= 0.40 THEN \'top30-40%\' WHEN cumulative_percentage > 0.40 AND cumulative_percentage <= 0.50 THEN \'top40-50%\' WHEN cumulative_percentage > 0.50 AND cumulative_percentage <= 0.60 THEN \'top50-60%\' WHEN cumulative_percentage > 0.60 AND cumulative_percentage <= 0.70 THEN \'top60-70%\' WHEN cumulative_percentage > 0.70 AND cumulative_percentage <= 0.80 THEN \'top70-80%\' WHEN cumulative_percentage > 0.80 AND cumulative_percentage <= 0.90 THEN \'top80-90%\' ELSE \'top90-100%\' END AS pincode_category FROM pincode_percentage ORDER BY week, cumulative_percentage ) where week is not null ); CREATE OR REPLACE TABLE cp_5 as ( select *,\"Created at\"::timestamp as Created_at from snitch_clickpost_track_order_dashboard_report where \"Courier Partner\" in (\'Delhivery Reverse\',\'Proship B2C Reverse\',\'Ekart Reverse\') and \"Created at\" >= \'2024-10-01 00:00:00\' and \"Out For Pickup Attempts\" IS NOT NULL AND \"Out For Pickup Attempts\" != \'\' AND \"Out For Pickup Attempts\" != \'0\' AND \"Out For Pickup Attempts\" != \'1\' ); CREATE OR REPLACE TABLE cp_6 AS ( SELECT \"Account Code\",AWB,ZONE,\"QC Type\",\"RTO AWB\",\"Order ID\",\"Created at\",\"Created at\"::timestamp as Created_at ,\"Order Date\",\"RVP Reason\",\"Drop Pincode\",\"Payment Mode\",\"Committed SLA\",\"Delivery Date\",\"Latest Remark\",\"RTO Mark Date\",\"Pickup Pincode\",\"Return Pincode\",\"Courier Partner\",\"OTP Verified Delivery\",\"Remark Of Last Pickup\",\"Out For Pickup Attempts\",\"Clickpost Unified Status\",\"OTP Verified Cancellation\",\"Out For Delivery Attempts\",\"Out For Pickup 1st Attempt\",\"Out For Pickup 2nd Attempt\",\"Out For Pickup 3rd Attempt\",\"Out For Delivery 1st Attempt\",\"Out For Delivery 2nd Attempt\",\"Out For Delivery 3rd Attempt\",\"Out For Delivery 4th Attempt\",\"Out For Delivery 5th Attempt\",\"Reason For Last Failed Pickup\",\"Remark Of First Failed Pickup\",\"Reason For First Failed Pickup\",\"Remark Of Last Failed Delivery\",\"Expected Date of Delivery (Max)\",\"Expected Date of Delivery (Min)\",\"Reason For Last Failed Delivery\",\"Remark Of First Failed Delivery\",\"TimeStamp Of Last Failed Pickup\",\"Reason For First Failed Delivery\",\"TimeStamp Of First Failed Pickup\",\"TimeStamp Of Last Failed Delivery\",\"TimeStamp Of First Failed Delivery\",\"Pickup Date\" FROM snitch_clickpost_track_order_dashboard_report where \"Created at\" >= \'2024-10-01\';",
                    "transaction": true
                }
            ) }}
